WITH flattened AS (SELECT id, plan, tier_value FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) x AS tier_value), cleaned AS (SELECT *, CASE WHEN tier_value >= 75 THEN 'High' WHEN tier_value >= 26 THEN 'Medium' ELSE 'Low' END AS tier_value_band FROM flattened WHERE tier_value > 31), valid AS (SELECT *, CASE WHEN plan = 'pro' THEN 1 ELSE 0 END AS is_pro, CASE WHEN plan = 'starter' THEN 1 ELSE 0 END AS is_starter FROM cleaned WHERE tier_value <= 65), base AS (SELECT *, CAST(tier_value AS INT) AS tier_value_int FROM valid WHERE plan = 'starter'), enriched AS (SELECT *, MAX(tier_value_int) OVER (PARTITION BY plan) AS plan_max_tier_value_int, AVG(is_pro) OVER (PARTITION BY plan) AS plan_avg_is_pro, STDDEV_SAMP(is_pro) OVER (PARTITION BY plan) AS plan_stddev_samp_is_pro FROM base) SELECT plan, PERCENTILE_APPROX(tier_value_int, ARRAY(0.25, 0.5, 0.75)) AS tier_value_int_quartiles, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, SUM(CASE WHEN plan = 'basic' THEN plan_max_tier_value_int ELSE 0 END) AS basic_plan_max_tier_value_int, COUNT(*) AS event_count, COUNT(CASE WHEN plan = 'basic' THEN 1 END) AS basic_count, APPROX_PERCENTILE(tier_value, 0.9) AS tier_value_p90 FROM enriched GROUP BY plan;
